import {notFound} from 'next/navigation'; import Link from 'next/link'; import {books,getBook} from '@/data/books'; import {BookArt} from '@/components/book-art'; import {Viewer} from '@/components/viewer'; import {StoryCard} from '@/components/story-card';
export function generateStaticParams(){return books.map(b=>({slug:b.slug}))}
export default async function Detail({params}:{params:Promise<{slug:string}>}){const book=getBook((await params).slug);if(!book)return notFound();return <main><section className="detail-hero wrap"><BookArt book={book} large/><div><p className="eyebrow">{book.category} · {book.pages}</p><h1>{book.title}</h1><p className="lead">{book.description}</p><p>{book.introduction}</p><dl><div><dt>For</dt><dd>{book.audience}</dd></div><div><dt>Format</dt><dd>Hardcover or digital keepsake</dd></div></dl><Link className="button" href="/stories">Explore the collection</Link></div></section><section className="cream detail-copy"><div className="wrap"><p className="eyebrow">An example chapter</p><h2>Made to be held, read, and <i>remembered.</i></h2><Viewer book={book}/></div></section><section className="wrap related"><div className="section-intro"><p className="eyebrow">Continue the journey</p><h2>More stories to <i>hold close.</i></h2></div><div className="story-grid">{books.filter(b=>b.slug!==book.slug).slice(0,3).map(b=><StoryCard key={b.slug} book={b}/>)}</div></section></main>}
